  function rulesPanel() {
    return `<p class="wf-intro">粘贴你的格式要求，逐项查看候选规则。未提及的字段保持未指定；只有明确确认的规则才会应用。</p><div class="wf-grid"><label class="field wide">格式要求<textarea id="wfRuleText" rows="5" placeholder="例如：论文标题黑体小二，正文宋体小四，1.5 倍行距，首行缩进 2 字符。">${esc(W.ruleText)}</textarea></label><label class="field">解析方式<select id="wfRuleMode"><option value="local" ${W.ruleMode==='local'?'selected':''}>本机解析</option><option value="deepseek" ${W.ruleMode==='deepseek'?'selected':''}>DeepSeek API</option></select></label><div class="wf-align-end">${btn('parse-rules','解析格式要求',true)}</div></div><p class="help">本机解析处理常见表达。DeepSeek 会收到这里的要求和规则字段说明；发送前会展示范围。</p>${warnings(W.ruleWarnings)}${conflictPanel(W.ruleConflicts)}${W.rules.length?`<div class="wf-section-head"><h3>候选规则 <span>${W.rules.length} 项</span></h3>${btn('confirm-all-rules','确认全部明确项')}</div><div class="wf-candidates">${W.rules.map((x,i)=>ruleCard(x,i,'rule')).join('')}</div><label class="check wf-conflict-check"><input id="wfRuleResolve" type="checkbox">已查看来源冲突，采用下方已确认的选择</label><div class="wf-footer">${btn('apply-rules','应用已确认规则',true)}</div>`:'<div class="wf-empty">解析后，候选值、单位、来源和待确认状态将在这里显示。</div>'}${ledgerPanel()}`;
  }
  function conflictPanel(conflicts) { return (conflicts||[]).length?`<section class="wf-conflicts"><h3>存在来源冲突 · 请逐项决定</h3>${conflicts.map(x=>`<article><b>${esc(x.path||`${label(x.role||x.target)} · ${label(x.field)}`)}</b><p>${esc(x.message||x.reason||'请确认差异')}</p>${('before' in x||'after' in x||'current' in x||'proposed' in x)?`<p>原规则：${esc(stateNames[x.beforeState]||'')} ${esc(printable(x.before??x.current??x.existing?.value))} ${esc(enumName(x.beforeUnit||''))} → 新规则：${esc(stateNames[x.afterState]||'')} ${esc(printable(x.after??x.proposed??x.incoming?.value))} ${esc(enumName(x.afterUnit||''))}</p>`:''}${x.source?`<small>${esc(printable(x.source))}</small>`:''}${x.sourceBefore?`<small>原来源：${esc(sourceText({source:x.sourceBefore}))}<br>新来源：${esc(sourceText({source:x.sourceAfter}))}</small>`:''}</article>`).join('')}</section>`:''; }
  function ruleCard(x,i,kind) {
    const decision=x.reviewDecision || (x.status==='confirmed'?'accept':x.status==='ignored'?'ignore':'pending');
    const ev=x.source?.page && x.source?.bbox;
    const unknown=x.state==='unspecified';
    const confidence=typeof x.confidence==='number'?` · ${Math.round(x.confidence*100)}%（模型或提取器自评）`:'';
    return `<article class="wf-candidate ${x.status==='confirmed'?'confirmed':''}" data-candidate="${i}"><div class="wf-card-heading"><h4>${esc(label(x.role||x.target))} · ${esc(label(x.field))}</h4><span class="wf-pill ${x.status==='confirmed'?'ok':''}">${esc(statusNames[x.status]||'待确认')}</span></div><p class="wf-rule-value">${esc(stateNames[x.state]||'未指定')} ${x.state==='set'?`<strong>${esc(printable(x.value))}</strong> <span>${esc(enumName(x.unit||''))}</span>`:''}</p><p class="wf-source">${esc(sourceText(x))}${esc(confidence)}${x.source?.userEdits?.length?' · 已人工修改':''}</p>${x.source?.originCandidate?`<p class="help">原始候选：${esc(stateNames[x.source.originCandidate.state])} ${esc(printable(x.source.originCandidate.value))} ${esc(enumName(x.source.originCandidate.unit))}</p>`:''}<p class="help">当前设置：${esc(printable(currentRuleValue(x)))}</p>${(x.target==='style'?S.profile.styles?.[x.role]:S.profile[x.target])?.enabled===false?'<p class="wf-warning">此对象的格式开关尚未启用。确认仅保存该值；如需执行，请在工作台明确开启对应的格式开关。</p>':''}${(x.measurement||x.source?.measurement)?`<p class="help">原始测量：${esc(measurementSummary(x.measurement||x.source.measurement))}</p>`:''}${x.reason?`<p class="help">${esc(x.reason)}</p>`:''}<div class="wf-candidate-fields"><label class="field">确认操作<select data-candidate-kind="${kind}" data-candidate-id="${i}" data-candidate-field="decision"><option value="pending" ${decision==='pending'?'selected':''}>待确认</option><option value="accept" ${decision==='accept'?'selected':''} ${unknown?'disabled':''}>接受候选</option><option value="edit" ${decision==='edit'?'selected':''}>修改后接受</option><option value="ignore" ${decision==='ignore'?'selected':''}>忽略</option><option value="unknown" ${decision==='unknown'?'selected':''}>保留未知</option></select></label><label class="field">字段状态<select data-candidate-kind="${kind}" data-candidate-id="${i}" data-candidate-field="state">${Object.entries(stateNames).map(([k,v])=>`<option value="${k}" ${x.state===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">值${valueEditor(x,i,kind)}</label><label class="field">单位${['line','indent'].includes(x.field)?`<select data-candidate-kind="${kind}" data-candidate-id="${i}" data-candidate-field="unit" ${x.state!=='set'?'disabled':''}>${(x.field==='line'?['pt','multiple']:['cm','chars']).map(v=>`<option value="${v}" ${x.unit===v?'selected':''}>${esc(enumName(v))}</option>`).join('')}</select>`:`<span class="wf-unit-value">${esc(enumName(x.unit||''))}</span>`}</label></div>${kind==='pdf'&&ev?btn('evidence','查看原页证据',false,`data-index="${i}"`):''}</article>`;
  }
  function ledgerPanel() { return `<details class="wf-ledger"><summary>规则来源记录 · ${W.ledger.length} 项</summary>${W.ledger.length?W.ledger.map(x=>`<article><b>${esc(label(x.role||x.target))} · ${esc(label(x.field))}</b><span>${esc(stateNames[x.state]||'设为')} ${esc(printable(x.value))} ${esc(enumName(x.unit||''))}</span><small>${esc(sourceText(x))}${x.templateVersion?` · 模板版本 ${esc(x.templateVersion)}`:''}</small></article>`).join(''):'<p class="help">确认应用后将在这里记录规则与来源。</p>'}</details>`; }
  async function parseRules(button) {
    const text=$('wfRuleText').value.trim();W.ruleText=text;W.ruleMode=$('wfRuleMode').value;if(!text)throw Error('请先填写格式要求');
    if(W.ruleMode==='deepseek'&&!await confirmSend('将发送你填写的格式要求，以及可用规则字段、类型和单位说明。不会发送当前 DOCX 正文或 PDF 页面。真实调用会计入你的 DeepSeek API 用量。'))return;
    await operation(button,'正在解析格式要求…',async()=>{const out=await api('rules/parse',{text,mode:W.ruleMode,profile:clone(S.profile)});W.rules=(out.items||[]).map(x=>({...x,status:'pending',reviewDecision:'pending'}));W.ruleWarnings=out.warnings||[];W.ruleConflicts=out.conflicts||[];renderWorkflow();setStatus(`${out.sourceMode==='deepseek'?'DeepSeek':'本机'}解析完成 · ${W.rules.length} 项候选${out.sourceMode==='deepseek'&&!out.liveVerified?' · 真实调用未验证':''}`);changed();});
  }
  async function applyRules(items,resolve=false,button=null) {
    const confirmed=items.filter(x=>x.status==='confirmed'&&x.state!=='unspecified');if(!confirmed.length)throw Error('请先确认至少一条明确规则');
    await operation(button,'正在检查规则冲突…',async()=>{const out=await api('rules/apply',{profile:clone(S.profile),items:confirmed,...(resolve?{resolveConflicts:true}:{})});if(out.conflicts?.length){W.ruleConflicts=out.conflicts;W.rules=clone(items);W.tab='rules';renderWorkflow();setStatus('来源存在冲突，请查看差异并确认最终选择',true);return;}if(!out.profile)throw Error('未返回可应用的格式方案');remember();S.profile=out.profile;W.ledger.push(...(out.ledger||confirmed));W.ruleConflicts=[];invalidate();render();renderWorkflow();setStatus(`已应用 ${confirmed.length} 项规则，可在工作台继续调整`);changed();});
  }
  function pdfPanel() {
    const p=selectedPdf();
    return `<p class="wf-intro">从公开发表 PDF 提取可测量的版式，查看原页证据，再确认模板。出版版式参考的用途与投稿规范分别记录。</p><section class="wf-box"><div class="wf-grid"><label class="field">期刊 / 来源名称<input id="wfPdfJournal" placeholder="例如：自建测试样例"></label><label class="field">年份<input id="wfPdfYear" type="number" min="1800" max="2200" placeholder="可留空"></label><label class="field">栏目 / 文章类型<input id="wfPdfType" placeholder="研究论文、综述等"></label><label class="field">用途<select id="wfPdfPurpose"><option value="publication_reference">出版版式参考</option><option value="official_submission">官方投稿规范（有来源时）</option><option value="user_requirements">用户明确要求</option></select></label></div><label class="wf-file-picker">＋ 导入参考 PDF<input id="wfPdfFiles" type="file" accept=".pdf,application/pdf" multiple></label><p class="help">本机读取和渲染；扫描件没有可用 OCR 时显示“需 OCR”。当前尚未导入的期刊不会显示学习完成。</p></section><div class="wf-pdf-list" aria-label="参考 PDF 文件">${W.pdfs.length?W.pdfs.map(p=>`<div class="wf-pdf-sample"><button type="button" data-wf="select-pdf" data-value="${esc(p.id)}" class="wf-pdf-item ${p.id===W.selectedPdf?'active':''}"><b>${esc(p.name)}</b><span>${esc(p.metadata?.journal||'未填写期刊')} · ${esc(p.metadata?.year||'年份未填')}</span><small>${esc(statusNames[p.status]||p.status||'待确认')}</small></button><label class="check"><input type="checkbox" data-template-pdf="${esc(p.id)}" ${W.templatePdfIds.includes(p.id)?'checked':''}>参与本次模板样本</label></div>`).join(''):'<p class="wf-empty">未提供参考 PDF。可先导入明确标注的自建样例。</p>'}</div>${p?`<section><div class="wf-section-head"><h3>${esc(p.name)}</h3><span class="wf-pill">${esc(statusNames[p.status]||p.status)}</span></div><p class="help">用途：${esc(purposeName(p.metadata?.purpose))} · ${p.pages?.length||p.pageCount||0} 页 · 来源指纹 ${esc((p.sourceHash||'未返回').slice(0,16))}</p>${warnings(p.warnings)}${(W.templatePdfIds.length>1)?`<p class="help">本次模板包含 ${W.templatePdfIds.length} 个选定样本。年份、栏目和用途各自记录；不同观察不会平均。</p>${conflictPanel(sampleDifferences())}`:''}${conflictPanel(p.templateConflicts||[])}${(p.candidates||[]).length?`<div class="wf-candidates">${p.candidates.map((x,i)=>ruleCard(x,i,'pdf')).join('')}</div><div class="wf-grid wf-template-save"><label class="field">模板名称<input id="wfTemplateName" value="${esc(p.metadata?.journal||p.name.replace(/\.pdf$/i,''))}"></label><div class="wf-align-end">${btn('save-template','保存已确认规则为新版本',true)}</div></div><p class="help">仅保存已确认的规则；忽略项与未知项仍保留在项目证据中。</p>`:'<p class="wf-warning">没有可执行的候选规则。请查看提取状态和限制；空结果不会保存为已学习模板。</p>'}</section>`:''}<section class="wf-templates"><div class="wf-section-head"><h3>本机模板版本</h3>${btn('refresh-templates','刷新')}</div><div id="wfTemplateList">${templateList()}</div></section>`;
  }
  function purposeName(x) { return ({publication_reference:'出版版式参考',official_submission:'官方投稿规范',user_requirement:'用户明确要求',user_requirements:'用户明确要求'})[x]||x||'出版版式参考'; }
  function templateList() { return W.templates.length?W.templates.map((t,i)=>`<article class="wf-template"><div><b>${esc(t.name)}</b><small>版本 ${esc(t.version||1)} · ${esc(purposeName(t.purpose))} · ${(t.items||t.rules||[]).length} 项规则</small>${t.changes?`<p class="help">版本变化：${esc(printable(t.changes))}</p>`:''}</div>${btn('apply-template','查看并应用',false,`data-index="${i}"`)}</article>`).join(''):'<p class="help">尚无已确认的参考模板。</p>'; }
  async function importPdfs(files) {
    const metadata={journal:$('wfPdfJournal').value.trim(),year:$('wfPdfYear').value?Number($('wfPdfYear').value):null,articleType:$('wfPdfType').value.trim(),purpose:$('wfPdfPurpose').value};
    const button=$('wfPdfFiles');await operation(button,'正在本机提取 PDF…',async()=>{let complete=0;for(const file of files){try{if(!/\.pdf$/i.test(file.name))throw Error('请选择 PDF 文件');if(file.size>50*1024*1024)throw Error('单份 PDF 请小于 50 MB');const data=await fileData(file);const out=await api('pdf/import',{name:file.name,data,metadata});const record={...out,name:file.name,metadata:clone(metadata),sourceData:out.sourceData||data,candidates:(out.candidates||[]).map(x=>({...x,status:'pending',reviewDecision:'pending'}))};W.pdfs.push(record);W.selectedPdf=record.id;complete++;}catch(e){W.pdfs.push({id:crypto.randomUUID(),name:file.name,metadata:clone(metadata),status:'failed',warnings:[e.message],candidates:[]});notifyError(e);}}renderWorkflow();setStatus(`已读取 ${complete} 份 PDF，请核对提取状态和候选证据`);changed();});
  }
  async function refreshTemplates() { try { const out=await api('templates');W.templates=[...(out.templates||[]),...W.templates.filter(t=>!(out.templates||[]).some(n=>n.id===t.id&&n.version===t.version))];if(W.tab==='pdf'&&$('wfTemplateList'))$('wfTemplateList').innerHTML=templateList(); } catch(e) { setStatus(e.message,true); } }
  async function saveTemplate(button) { const p=selectedPdf(),samples=templateSamples(),items=samples.flatMap(p=>(p.candidates||[]).filter(x=>x.status==='confirmed'&&x.state!=='unspecified'));if(sampleDifferences().length)throw Error('所选样本存在不同规则，请查看差异并忽略冲突候选或修改为最终选择');if(!items.length)throw Error('请先接受或修改并确认至少一项候选规则');const name=$('wfTemplateName').value.trim();if(!name)throw Error('请填写模板名称');await operation(button,'正在保存模板版本…',async()=>{const out=await api('templates/save',{name,purpose:p.metadata?.purpose==='user_requirement'?'user_requirements':p.metadata?.purpose||'publication_reference',metadata:{...p.metadata,samples:samples.map(q=>({name:q.name,...q.metadata}))},items,pdfIds:samples.map(q=>q.id)});if(out.conflicts?.length){p.templateConflicts=out.conflicts;renderWorkflow();setStatus('样本存在候选冲突，请忽略冲突项或修改后再保存',true);return;}if(!out.template)throw Error('模板未保存');for(const sample of samples)sample.status=(sample.candidates||[]).every(x=>['confirmed','ignored'].includes(x.status)||x.reviewDecision==='unknown')?'confirmed':'pending_confirmation';W.templates.unshift(out.template);renderWorkflow();setStatus(`已保存模板“${out.template.name}”版本 ${out.template.version||1}`);changed();}); }
  async function viewEvidence(index) {
    const p=selectedPdf(),x=p?.candidates[index],s=x?.source||{};if(!x||!s.page)throw Error('该候选缺少页码证据');
    $('wfEvidenceBody').innerHTML=`<p class="help">${esc(p.name)} · 第 ${esc(s.page)} 页 · 左上角为原点 · 显示旋转后的 PDF 磅坐标</p><p>${esc(s.evidence||s.text||'未提供证据文字')}</p><p class="help">原始测量：${esc(measurementSummary(x.measurement??s.measurement??x.value))}</p><details class="wf-measurement"><summary>原始测量与坐标明细</summary><pre>${esc(JSON.stringify({measurement:x.measurement??s.measurement??x.value,method:s.method,bbox:s.bbox,coordinateSystem:s.coordinateSystem},null,2))}</pre></details><div class="wf-evidence-stage" id="wfEvidenceStage"><p class="wf-empty">正在渲染原页…</p></div><p class="help">高亮框对应候选来源坐标。字号和位置是测量值；Word 行距、缩进与段距仍需人工确认。</p>`;
    $('wfEvidence').showModal();
    try{const response=await fetch(`/api/pdf/${encodeURIComponent(p.id)}/page/${encodeURIComponent(s.page)}`);if(!response.ok)throw Error('原页渲染失败');const blob=await response.blob();if(!$('wfEvidence').open)return;W.evidenceUrl=URL.createObjectURL(blob);const img=document.createElement('img');img.src=W.evidenceUrl;img.alt=`${p.name}第 ${s.page} 页`;img.addEventListener('load',()=>{
      const stage=$('wfEvidenceStage');if(!stage)return;stage.innerHTML='';const wrapper=document.createElement('div');wrapper.className='wf-evidence-page';wrapper.append(img);
      const pages=Array.isArray(p.pages)?p.pages:[],page=pages.find(q=>(q.page||q.number)===s.page)||pages[s.page-1]||{};
      const dims=s.pageSize||page.size||[];const width=page.width||page.widthPt||s.pageWidth||dims[0],height=page.height||page.heightPt||s.pageHeight||dims[1];
      let box=Array.isArray(s.bbox)?s.bbox:[s.bbox?.x0,s.bbox?.y0,s.bbox?.x1,s.bbox?.y1];
      if(width&&height&&box.length===4&&box.every(Number.isFinite)) { const overlay=document.createElement('div');overlay.className='wf-evidence-box';Object.assign(overlay.style,{left:`${box[0]/width*100}%`,top:`${box[1]/height*100}%`,width:`${(box[2]-box[0])/width*100}%`,height:`${(box[3]-box[1])/height*100}%`});overlay.setAttribute('aria-label','候选证据区域');wrapper.append(overlay); } else { const notice=document.createElement('p');notice.className='wf-warning';notice.textContent='来源缺少有效页面尺寸或坐标，无法精确绘制证据框。';stage.append(notice); }
      stage.append(wrapper);
    });img.addEventListener('error',()=>{$('wfEvidenceStage').textContent='页面图片无法显示，请重试。';});}catch(e){$('wfEvidenceStage').innerHTML=`<p class="wf-warning">${esc(e.message)}</p>`;}
  }
  function paginationPanel(d) {
    const failed=(d?.report?.checks||[]).some(c=>c.status==='fail'),available=W.renderStatus?.available;
    return `<section class="form-section"><h3>真实分页参考</h3><p class="help">使用已生成的 DOCX 输出，由本机 LibreOffice 渲染为 PDF。工作台中间仍为结构预览；此参考不会代替 Word／WPS 实测。</p>${btn('render-output',W.rendering?'正在生成分页参考…':'生成真实分页参考（LibreOffice）',false,!d?.result||failed||S.busy||W.rendering?'disabled':'')}${available===false?`<p class="warning">${esc(W.renderStatus.message||'未检测到可用的本机分页渲染环境。')}</p>`:''}${isResultStale(d)?'<p class="warning">当前规则已有变化，本次参考使用先前已验证的输出；如需查看当前规则效果，请先重新排版。</p>':''}${d?.report?.pagination?`<p class="help">上次参考记录：${d.report.pagination.pageCount||0} 页 · 视觉复核待完成 · Word／WPS 尚未实测</p>`:''}</section>`;
  }
  async function loadRenderStatus() {try{W.renderStatus=await api('render/status');}catch(e){W.renderStatus={available:false,message:'分页服务暂不可用：'+e.message};}if(S.tab==='quality'&&doc())renderInspector();}
  async function generatePagination(button) {
    const d=doc();if(!d?.result||!d.report||(d.report.checks||[]).some(c=>c.status==='fail'))throw Error('请先确认排版并生成检查通过的 DOCX 输出');if(W.rendering)return;
    const source=d.result,report=d.report,name=d.name,wasStale=isResultStale(d);W.rendering=true;button.disabled=true;$('wfPaginationBody').innerHTML='<p class="wf-empty">正在调用本机 LibreOffice 生成分页参考…</p>';$('wfPaginationStatus').textContent='渲染较复杂文档可能需要数十秒。';$('wfPagination').showModal();
    try{const status=await api('render/status');W.renderStatus=status;if(!status.available){$('wfPaginationBody').innerHTML=warnings([status.message||'未检测到 LibreOffice，请导出 DOCX 后在 Word／WPS 查看分页。']);$('wfPaginationStatus').textContent='分页参考未生成';return;}const info=await api('render',{data:source});if(info.status!=='rendered'||!info.id||!info.pageCount){$('wfPaginationBody').innerHTML=warnings(info.warnings||['未返回可显示的分页结果']);$('wfPaginationStatus').textContent='分页参考未生成';return;}if(info.sourceSHA256&&report.resultSHA256&&info.sourceSHA256!==report.resultSHA256)throw Error('分页参考的源输出指纹不一致，请重新生成');W.pagination={info,documentId:d.id,name,page:1,wasStale};const {id,...metadata}=info;report.pagination=metadata;changed();if($('wfPagination').open){renderPaginationViewer();await loadPaginationPage();}else toast(`已生成“${name}”的 ${info.pageCount} 页 LibreOffice 参考；视觉复核仍待完成`);
    }catch(e){$('wfPaginationStatus').textContent='分页参考生成失败';$('wfPaginationBody').innerHTML=warnings([e.message]);notifyError(e);}finally{W.rendering=false;if(S.tab==='quality')renderInspector();}
  }
  function renderPaginationViewer() {
    const p=W.pagination;if(!p)return;const aliases=p.info.fontSubstitutions||{},aliasItems=Array.isArray(aliases)?aliases.map(printable):Object.entries(aliases).map(([a,b])=>`${a} → ${b}`);
    $('wfPaginationStatus').textContent=`${p.name} · ${p.info.pageCount} 页 · 视觉复核待完成`;
    $('wfPaginationBody').innerHTML=`${p.wasStale?'<p class="wf-warning">本参考来自先前已验证的 DOCX 输出，未使用当前已变化的规则。</p>':''}<section class="wf-font-substitutions"><b>本次渲染配置的字体替代</b><p>${esc(aliasItems.length?aliasItems.join('；'):'未报告额外的替代配置；实际字形仍需复核。')}</p><small>本参考的替代配置不会改变 DOCX 中保存的字体名称。</small></section>${warnings((p.info.warnings||[]).filter(w=>!String(w).includes('明确字体替代')&&!String(w).startsWith('这是LibreOffice生成的真实分页参考')))}<div class="wf-pagination-toolbar">${btn('render-prev','上一页',false,p.page<=1?'disabled':'')}<span id="wfPaginationNumber">第 ${p.page} / ${p.info.pageCount} 页</span>${btn('render-next','下一页',false,p.page>=p.info.pageCount?'disabled':'')}${btn('render-download','下载分页参考 PDF')}</div><div class="wf-pagination-stage" id="wfPaginationStage"><p class="wf-empty">正在读取页面…</p></div><p class="help">源输出指纹：${esc((p.info.sourceSHA256||'未返回').slice(0,20))} · 已有格式检查报告继续保留；此渲染结果的视觉复核尚未完成。</p>`;
  }
  async function loadPaginationPage() {
    const p=W.pagination;if(!p)return;const ticket=++W.paginationRequest,page=p.page;$('wfPaginationStage').innerHTML='<p class="wf-empty">正在读取第 '+page+' 页…</p>';
    try{const response=await fetch(`/api/render/${encodeURIComponent(p.info.id)}/page/${page}`);if(!response.ok){const error=await response.json().catch(()=>({}));throw Error(error.error||'页面读取失败，请重新生成分页参考');}const blob=await response.blob();if(ticket!==W.paginationRequest||!$('wfPagination').open)return;if(W.paginationUrl)URL.revokeObjectURL(W.paginationUrl);W.paginationUrl=URL.createObjectURL(blob);const img=document.createElement('img');img.src=W.paginationUrl;img.alt=`${p.name} · LibreOffice 分页参考第 ${page} 页`;img.onload=()=>{if(ticket===W.paginationRequest)$('wfPaginationStatus').textContent=`${p.name} · 第 ${page} / ${p.info.pageCount} 页 · 视觉复核待完成`;};img.onerror=()=>{if(ticket===W.paginationRequest)$('wfPaginationStage').innerHTML=warnings(['分页图片无法显示，请重新生成']);};$('wfPaginationStage').replaceChildren(img);$('wfPaginationStage').scrollTop=0;
    }catch(e){if(ticket===W.paginationRequest)$('wfPaginationStage').innerHTML=warnings([e.message]);}
  }
  async function downloadPagination() {const p=W.pagination;if(!p)return;const response=await fetch(`/api/render/${encodeURIComponent(p.info.id)}/download`);if(!response.ok){const info=await response.json().catch(()=>({}));throw Error(info.error||'分页 PDF 下载失败，请重新生成');}blobDownload(await response.blob(),p.name.replace(/\.docx$/i,'')+'_LibreOffice分页参考.pdf');}
  function structurePanel() {
    const d=doc();if(!d)return '<p class="wf-empty">请先在工作台打开一份 DOCX 文档。</p>';
    const items=d.aiCandidates||[],summary=d.aiSummary||{},locks=d.aiLocks||{};
    return `<p class="wf-intro">${esc(d.name)} · ${d.model.paragraphs.length} 个段落。建议会显示原分类、建议分类与理由；确认并锁定后，后续识别尊重人工决定。</p><div class="wf-footer wf-left">${btn('structure-local','本机结构分析',true)}${btn('structure-ai','DeepSeek 结构识别')}${btn('lock-current','锁定当前人工分类')}</div><p class="help">本机分析使用结构线索；DeepSeek 分析发送段落、全文大纲和规则。置信度是模型自评，不能作为真实准确率。</p><label class="field">补充说明<textarea id="wfStructureNotes" placeholder="例如：正文标题最多三级。">${esc(d.aiRuleNotes||'')}</textarea></label>${warnings(summary.warnings)}${warnings(summary.conflicts)}${warnings(summary.issues)}${summary.omitted?warnings([`识别器遗漏 ${Array.isArray(summary.omitted)?summary.omitted.length:summary.omitted} 个段落，请复核。`]):''}${summary.missing?.length?warnings([`遗漏 ${summary.missing.length} 个段落，需重新识别或人工确认。`]):''}<div class="wf-section-head"><h3>逐段复核 <span>${items.length} 项建议 · ${Object.values(locks).filter(Boolean).length} 项锁定</span></h3>${items.length?btn('apply-structure','应用已勾选建议并锁定',true):''}</div><div class="wf-structure-list">${items.length?items.map((x,i)=>{const p=d.model.paragraphs.find(p=>p.id===x.id),old=d.roles[x.id]||p?.role||x.current_role;return `<article class="wf-structure-card"><div class="wf-structure-top"><label class="check"><input type="checkbox" data-structure-choice="${i}" ${x.reviewSelected?'checked':''} ${locks[x.id]?'disabled':''}>${esc(x.text||p?.text||x.id)}</label><label class="check"><input type="checkbox" data-structure-lock="${esc(x.id)}" ${locks[x.id]?'checked':''}>锁定</label></div><div class="wf-structure-fields"><span>原分类：<b>${esc(label(old))}</b></span><label class="field">建议分类<select data-structure-role="${i}" ${locks[x.id]?'disabled':''}>${Object.entries(roleNames).map(([k,v])=>`<option value="${k}" ${x.role===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label></div><p class="help">${esc(x.reason||'未提供理由')}${Number.isFinite(x.confidence)?` · ${Math.round(x.confidence*100)}%（模型自评）`:''}</p>${x.evidence?`<p class="wf-source">${esc(printable(x.evidence))}</p>`:''}</article>`;}).join(''):'<p class="wf-empty">点击本机分析或 DeepSeek 识别，生成全文结构建议。</p>'}</div><details class="wf-ledger"><summary>所有段落的人工锁定</summary>${d.model.paragraphs.map(p=>`<label class="check wf-lock-row"><input type="checkbox" data-structure-lock="${esc(p.id)}" ${locks[p.id]?'checked':''}><span>${esc(label(d.roles[p.id]||p.role))} · ${esc(p.text.slice(0,100)||'空段落')}</span></label>`).join('')}</details>`;
  }
  async function analyzeStructure(mode,button) {
    const d=doc();if(!d)throw Error('请先打开文档');d.aiRuleNotes=$('wfStructureNotes').value;
    if(mode==='deepseek'&&!await confirmSend(`将发送“${d.name}”中 ${d.model.paragraphs.length} 个段落的文本、全文结构线索、当前规则，以及你填写的补充说明。DOCX 文件本身、表格数值与公式表达式不会作为编辑要求发送。调用计入 DeepSeek API 用量。`))return;
    await operation(button,mode==='local'?'正在本机分析全文结构…':'DeepSeek 正在分析全文结构…',async()=>{const out=await api(mode==='local'?'structure':'deepseek/analyze',{id:d.id,profile:clone(S.profile),notes:d.aiRuleNotes,locks:d.aiLocks||{},roles:d.roles});const items=out.items||out.suggestions||[],ids=new Set(d.model.paragraphs.filter(p=>p.text.trim()&&!['cell','equation'].includes(p.role)).map(p=>p.id)),seen=new Set(),errors=[];const valid=items.filter(x=>{if(!ids.has(x.id)){errors.push(`未知段落标识 ${x.id}`);return false;}if(seen.has(x.id)){errors.push(`重复段落标识 ${x.id}`);return false;}seen.add(x.id);if(!roleNames[x.role]){errors.push(`段落 ${x.id} 的建议分类无效`);return false;}return true;});const missing=[...ids].filter(id=>!seen.has(id));d.aiCandidates=valid.map(x=>({...x,reviewSelected:false}));d.aiSummary={...out,items:valid,warnings:[...(out.warnings||[]),...errors],missing};renderWorkflow();setStatus(`${mode==='local'?'本机结构分析':'DeepSeek 结构识别'}已返回 ${valid.length} 项建议${missing.length?`，${missing.length} 个段落尚需复核`:''}`);changed();});
  }
  function applyStructure() { const d=doc();const items=(d?.aiCandidates||[]).filter(x=>x.reviewSelected&&!d.aiLocks?.[x.id]);if(!items.length)throw Error('请先勾选要应用的段落建议');remember();d.aiLocks ||= {};for(const x of items){d.roles[x.id]=x.role;d.aiLocks[x.id]=true;x.reviewSelected=false;}invalidate(false);render();renderWorkflow();setStatus(`已确认并锁定 ${items.length} 个段落，可在工作台撤销`);changed(); }
  function projectPanel() {return `<p class="wf-intro">项目包含原稿、规则来源、段落分类与锁定、局部格式、表格和公式设置、PDF 证据、模板版本及检查结果。</p><label class="field">项目名称<input id="wfProjectName" value="${esc(W.projectName)}"></label><div class="wf-footer wf-left">${btn('save-project','保存到本机',true)}${btn('export-project','导出完整项目 JSON')}${btn('import-project','导入项目')}</div><p class="help">API 密钥不写入项目。服务器项目保存在本机项目目录；自动恢复副本保存在当前浏览器的 IndexedDB。完整 JSON 含原稿内容，请按文档需要妥善保存。</p><section class="wf-box"><div class="wf-section-head"><h3>本机自动恢复</h3><span id="wfAutosaveStatus" class="wf-pill">${W.recovery?'等待恢复或清除':W.db?'已启用':'不可用'}</span></div><div class="wf-footer wf-left">${btn('restore-autosave','恢复上次工作')}${btn('clear-autosave','清除恢复副本')}</div></section><section><div class="wf-section-head"><h3>已保存项目</h3>${btn('refresh-projects','刷新')}</div><div id="wfProjectList"><p class="help">正在读取项目列表…</p></div></section>`;}
