      const flow=state.workflow||{},pdfs=[];W.selectedPdf=null;for(const saved of flow.pdfs||[]){if(!saved.sourceData){pdfs.push(pick(saved,pdfFields));continue;}const existing=(out.pdfRecords||out.pdfs||[]).find(p=>p.id===saved.id||p.id===out.pdfIdMap?.[saved.id]||p.originalId===saved.id||p.sourceHash===saved.sourceHash);const data=existing||await api('pdf/import',{name:saved.name,data:saved.sourceData,metadata:saved.metadata||{}});pdfs.push({...data,...pick(saved,pdfFields),id:data.id});if(flow.selectedPdf===saved.id)W.selectedPdf=data.id;}
