  function batchPanel() { const b=W.batch;return `<p class="wf-intro">共 ${S.docs.length} 份文档。逐份排版并检查，成功结果会保留；取消停止后续处理，失败项可单独重试。</p><div class="wf-footer wf-left">${btn('start-batch','预览并开始批量排版',true,(!S.docs.length||b&&['queued','running','canceling','cancelling'].includes(b.status))?'disabled':'')}${b?btn('cancel-batch','取消任务',false,!['queued','running','canceling','cancelling'].includes(b.status)?'disabled':''):''}${b?btn('retry-batch','重试未完成项',false,!(b.items||[]).some(x=>['failed','cancelled'].includes(x.status))||['queued','running'].includes(b.status)?'disabled':''):''}</div>${b?.previousId?'<p class="wf-warning">已成功项沿用原任务确认的设置；当前修复设置仅用于重试未完成项。若修改了全文规则，请开始新批量任务，生成规则一致的新输出。</p>':''}<div id="wfBatchProgress">${b?batchProgress():`<p class="wf-empty">开始后将在这里显示每份文档的真实状态和错误信息。</p>`}</div>${b?`<div class="wf-footer">${btn('download-batch','下载成功 DOCX 与报告 ZIP',true,(b.items||[]).some(x=>['success','completed','complete'].includes(x.status))?'':'disabled')}</div>`:''}`; }
  function batchProgress() {const b=W.batch,items=b.items||[],progress=typeof b.progress==='number'?b.progress:b.progress?.percent,done=items.filter(x=>['success','complete','completed','failed','cancelled'].includes(x.status)).length,total=items.length||S.docs.length,pct=progress===undefined?(total?done/total*100:0):progress<=1?progress*100:progress;return `<div class="wf-batch-summary"><b>${esc(statusNames[b.status]||b.status)}</b><span>${done} / ${total} 份已结束</span><progress value="${Math.min(100,Math.max(0,pct))}" max="100" aria-label="批量任务进度"></progress></div>${items.map(x=>`<article class="wf-task"><div><b>${esc(x.name||x.id)}</b><p class="help">${esc(x.error||'')}</p></div><span class="wf-pill ${['success','complete','completed'].includes(x.status)?'ok':x.status==='failed'?'bad':''}">${esc(statusNames[x.status]||x.status)}</span></article>`).join('')}`;}
