    const dialog=$('wfPreview');$('wfPreviewBody').innerHTML='<p class="wf-empty">正在生成逐项变更预览…</p>';const confirmButton=dialog.querySelector('[data-wf=confirm-preview]');confirmButton.disabled=true;dialog.showModal();let cancelled=false;const mark=()=>{cancelled=true;};const cancelLoading=e=>{if(e.target.closest('[data-wf]')?.dataset.wf==='cancel-preview')dialog.close();};document.addEventListener('click',cancelLoading);dialog.addEventListener('close',mark,{once:true});
