  function updateCandidate(input) {const collection=input.dataset.candidateKind==='pdf'?selectedPdf()?.candidates:W.rules,x=collection?.[Number(input.dataset.candidateId)];if(!x)return;const field=input.dataset.candidateField,before={value:clone(x.value),state:x.state,unit:x.unit};if(field==='decision'){x.reviewDecision=input.value;x.status=['accept','edit'].includes(input.value)?'confirmed':input.value==='ignore'?'ignored':'pending';if(input.value==='unknown'){x.state='unspecified';x.value=null;}if(input.value==='accept'&&(x.state==='unspecified'||x.state==='set'&&(x.value===null||x.value===undefined||x.value===''))){x.status='pending';x.reviewDecision='pending';}}else if(field==='value'){if(input.value.trim()===''){x.value=null;x.state='unspecified';x.status='pending';x.reviewDecision='unknown';}else if(typeof x.value==='number'||typeof currentRuleValue(x)==='number'||ruleMeta(x).type==='number'){const value=Number(input.value);if(!Number.isFinite(value))throw Error('此规则需要有效数值');x.value=value;x.reviewDecision='edit';x.status='confirmed';}else if(typeof x.value==='boolean'||ruleMeta(x).type==='bool'){x.value=input.value==='true';x.reviewDecision='edit';x.status='confirmed';}else{x.value=input.value;x.reviewDecision='edit';x.status='confirmed';}}else{x[field]=input.value||null;if(field==='state'&&input.value==='unspecified'){x.status='pending';x.reviewDecision='unknown';}else if(x.state==='set'&&(x.value===null||x.value===undefined||x.value==='')){x.reviewDecision='pending';x.status='pending';}else{x.reviewDecision='edit';x.status='confirmed';}}if(['value','state','unit'].includes(field))recordCandidateEdit(x,before);renderWorkflow();changed();}
